import { test, expect } from '@playwright/test';

test.describe('Homepage Hero Section - Mobile Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display mobile-specific hero content when viewport is small', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify mobile hero title is visible
    const mobileTitle = page.getByRole('heading', { name: /mobile hero title/i });
    await expect(mobileTitle).toBeVisible();

    // Verify mobile hero description is visible
    const mobileDescription = page.getByText(/short mobile description/i);
    await expect(mobileDescription).toBeVisible();

    // Verify mobile CTA button is visible and clickable
    const mobileCta = page.getByRole('button', { name: /get started/i });
    await expect(mobileCta).toBeVisible();
    await expect(mobileCta).toBeEnabled();

    // Verify desktop hero title is NOT visible
    const desktopTitle = page.getByRole('heading', { name: /desktop hero title/i });
    await expect(desktopTitle).not.toBeVisible();
  });

  test('should display desktop hero content when viewport is large', async ({ page }) => {
    // Set viewport to desktop size
    await page.setViewportSize({ width: 1920, height: 1000 });

    // Verify desktop hero title is visible
    const desktopTitle = page.getByRole('heading', { name: /desktop hero title/i });
    await expect(desktopTitle).toBeVisible();

    // Verify desktop hero description is visible
    const desktopDescription = page.getByText(/detailed desktop description/i);
    await expect(desktopDescription).toBeVisible();

    // Verify desktop CTA button is visible and clickable
    const desktopCta = page.getByRole('button', { name: /explore features/i });
    await expect(desktopCta).toBeVisible();
    await expect(desktopCta).toBeEnabled();

    // Verify mobile hero title is NOT visible
    const mobileTitle = page.getByRole('heading', { name: /mobile hero title/i });
    await expect(mobileTitle).not.toBeVisible();
  });
});
